def f(gin):
    A = np.array(gin); H,W=A.shape
    bg=int(np.bincount(A.flat).argmax())
    col=min(sorted(range(10)), key=lambda c:(A==c).sum()) if False else None
    for c_ in range(10):
        pts=[(r,ii) for r,ii in zip(*np.where(A==c_))]
        if len(pts)>=2 and (len(set(r for r,_ in pts))==len(set(i for _,i in pts)) and max(i)-min(i)==max(r)-min(r)):
            dr=pts[-1][0]-pts[0][0]; dc=pts[-1][1]-pts[0][1]
            if abs(dr)==abs(dc) and dr!=0:
                return col,c_,pts,(dr//abs(dr),dc//abs(dc))
    return None

