import numpy as np,json
def solve(A):
    A=np.array(A); H,W=A.shape
    bg=np.bincount(A.flatten()).argmax()
    masks=(A!=bg) & (A!=2)   # treat everything non-bg,non-2 as walls? test
    seeds=[(r,c) for r in range(H) for c in range(W) if A[r,c]==3]
    starts=[(r,c) for r in range(H) for c in range(W) if A[r,c]==2]
    def ok(r,c): return 0<=r<H and 0<=c<W and not masks[r,c]
    from collections import deque
    dist={p:0 for p in starts}; par={}
    q=deque(starts)
    while q:
        p=q.popleft()
        if any(p==s for s in seeds): break
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            q2=(p[0]+dr,p[1]+dc)
            if q2 not in dist and ok(*q2):
                dist[q2]=dist[p]+1; par[q2]=p; q.append(q2)
    pat=set(); cur=None
    for s in seeds:
        if s in dist:
            cur=s; break
    out=A.copy()
    while cur in par: out[cur]; cur=par[cur]
    for (r,c) in pat: out[r,c]=3
    return out,(starts,seeds,bg,masks,dist)
for i in range(1,9):
    pred,_=solve(G[f'Demo pair {i} input'])
    exp=np.array(G[f'Demo pair {i} output'])
    print(f'pair{i} match:', bool((pred==exp).all()))

