def solve(A):
    A=np.array(A); H,W=A.shape
    bg=np.bincount(A.flatten()).argmax()
    mask=(A!=bg)&(A!=2)   # 2 = marker start; everything else wall except 3 seeds
    seeds=[tuple(p) for p in np.argwhere(A==3)]
    starts=[tuple(p) for p in np.argwhere(A==2)]
    out=A.copy()
    from collections import deque
    dist={p:0 for p in starts}
    par={p:None for p in starts}
    q=deque(starts)
    while q:
        p=q.popleft()
        for dr in(-1,0,1):
            for dc in(-1,0,1):
                q2=(p[0]+dr,p[1]+dc)
                if 0<=q2[0]<H and 0<=q2[1]<W and q2 not in dist and not mask[q2[0],q2[1]]:
                    dist[q2]=dist[p]+1; par[q2]=p; q.append(q2)
    if not seeds: return out
    best=None
    for s in seeds:
        if s in dist:
            pat=set(); cur=s
            while par[cur]:
                pat.add(cur); cur=par[cur]
            key=(len(pat),dist[s],s)
            if best is None or key<best[0]: best=key,pat
    for (r,c) in best[1]: out[r,c]=3
    return out,best
